/* DM - GADGET HUB | VYRA Risk OS. Native JS single-page frontend.
   No mock responses in authenticated partner workspaces. */
'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s===undefined||s===null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nfmt=n=>Number(n||0).toLocaleString('en-IN');
const inr=n=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:0});
const date=s=>{try{return new Date(s).toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch{return String(s)}};
const state={boot:null,me:null,tab:'pulse',org:null,orgs:[],page:1,filter:'ALL',search:'',riskResult:null,pendingChallenge:null,sourceView:null};
let activeFetch=0;
const themes={midnight:'Midnight Mint',cloud:'Cloud Blue',lemon:'Lemon Atelier',arctic:'Arctic Signal'};
function setTheme(t){if(!themes[t])return;document.body.setAttribute('data-theme',t);localStorage.setItem('vyra-theme',t);const s=$('theme-select');if(s)s.value=t;}
setTheme(localStorage.getItem('vyra-theme')||'midnight');
function toast(m,error=false){const root=$('toast');const item=document.createElement('div');item.className='toast-msg'+(error?' error':'');item.textContent=m;root.appendChild(item);setTimeout(()=>item.remove(),4300);}
async function request(path,{method='GET',body,raw=false}={}){
  const opts={method,credentials:'same-origin',headers:{}};
  if(method!=='GET'&&state.me?.csrf)opts.headers['X-CSRF-Token']=state.me.csrf;
  if(body!==undefined){if(raw){opts.body=body;opts.headers['Content-Type']='text/csv';}else{opts.body=JSON.stringify(body);opts.headers['Content-Type']='application/json';}}
  let res;
  try{res=await fetch('/api'+path,opts)}catch{throw new Error('Cannot reach the local server. Start run.bat and refresh.');}
  let json;try{json=await res.json()}catch{throw new Error('Unexpected server response');}
  if(!res.ok){if(res.status===401&&state.me){state.me=null;authView();}throw new Error(json.detail||json.error||'Operation failed');}
  return json;
}
function apiPath(p){return p+(p.includes('?')?'&':'?')+'workspace='+encodeURIComponent(state.org??state.me?.org_id??'');}
function safeRun(p){Promise.resolve(p).catch(e=>toast(e.message||'Unexpected error',true));}
function tag(x){const normalized=String(x||'').toLowerCase().replace(/ /g,'_');return `<span class="tag ${esc(normalized)}">${esc(x||'—')}</span>`;}
function pillScore(n){return `<span class="scorebar"><b>${Number(n)}</b><span class="scorebar-track"><span class="scorebar-fill ${n>=75?'high':n>=50?'medium':''}" style="width:${Math.max(0,Math.min(100,n))}%"></span></span></span>`;}
function heading(k,title,subtitle,actions=''){return `<div class="section-heading"><div><div class="eyebrow">${esc(k)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="actions">${actions}</div></div>`;}
function cardTitle(title,desc='',end=''){return `<div class="card-header"><div><div class="card-title">${esc(title)}</div>${desc?`<div class="card-desc">${esc(desc)}</div>`:''}</div>${end}</div>`;}
function empty(title,message,button=''){return `<div class="empty"><span class="empty-icon">◈</span><strong>${esc(title)}</strong><p>${esc(message)}</p>${button?`<div style="margin-top:17px">${button}</div>`:''}</div>`;}
function aboutCreator(){return `<div class="auth-founder"><div class="credit-dot">DM</div><div><strong>Created by Divy Mathur</strong><small><a href="mailto:divymathur12345678901@gmail.com">divymathur12345678901@gmail.com</a></small></div></div>`;}
function authShell(content){$('app').innerHTML=`<div class="auth-outer"><section class="auth-visual"><div class="auth-wordmark"><span class="brand-mark"><span>DM</span></span><div>DM – GADGET HUB <small style="display:block;font-size:9px;letter-spacing:2.4px;color:var(--muted);margin-top:3px">VYRA / RISK OPERATING SYSTEM</small></div></div><div class="auth-hero"><span class="mini">◉ FINTECH RISK OPERATIONS / V2.0</span><h1>Make every<br>decision <em>count.</em></h1><p>A private command center to investigate high-value electronics payments, stop suspicious activity, and manage chargebacks with evidence. Your data. Your partners. Your control.</p><div class="auth-stats"><div><strong>4</strong><small>Decision bands</small></div><div><strong>24/7</strong><small>Risk visibility</small></div><div><strong>01</strong><small>Owner-controlled platform</small></div></div></div><div class="auth-bottom">DM GADGET HUB // EDUCATIONAL RISK PLATFORM · NOT A PAYMENT GATEWAY</div></section><section class="auth-form-side"><div class="auth-box"><div class="eyebrow">PRIVATE ACCESS · VYRA IDENTITY</div>${content}${aboutCreator()}<div class="outline-note">Theme <span class="theme-dots" style="display:inline-flex;margin-left:10px;vertical-align:middle">${Object.keys(themes).map(t=>`<button type="button" title="${esc(themes[t])}" aria-label="${esc(themes[t])}" aria-pressed="${document.body.dataset.theme===t}" data-act="theme-${t}" class="theme-dot" style="background:${({midnight:'#ccff72',cloud:'#305efe',lemon:'#f5e44a',arctic:'#48b7ff'})[t]}"></button>`).join('')}</span></div></div></section></div>`;}
function authView(){
  const invite=new URLSearchParams(location.search).get('invite');
  if(invite){authShell('<h2>Partner activation</h2><p>Verify your invitation and choose a strong password to enter your organization\'s private risk workspace.</p><div id="invite-info" class="strip">Checking invitation…</div><form id="activation-form"><div class="form-group"><label class="form-label">YOUR DISPLAY NAME</label><input name="name" required minlength="2" placeholder="Full name"/></div><div class="form-group"><label class="form-label">NEW PASSWORD · 12+ CHARACTERS</label><input name="password" type="password" minlength="12" required autocomplete="new-password"/></div><button class="btn primary" type="submit">Activate partner account ↗</button></form><p style="margin-top:20px"><a href="/" class="muted">← Back to sign in</a></p>');safeRun(request('/auth/invite/'+encodeURIComponent(invite)).then(info=>{$('invite-info').innerHTML=`<strong>${esc(info.workspace)}</strong><br>Invitation for ${esc(info.email)} · ${esc(info.role)}`;}).catch(e=>{$('invite-info').textContent=e.message;$('activation-form').style.display='none';}));return;}
  if(state.pendingChallenge){authShell(`<h2>Check your email</h2><p>Enter the one-time six-digit code sent to <b>${esc(state.pendingChallenge.masked_email)}</b>. It expires in 10 minutes.</p><form id="otp-form"><div class="form-group"><label class="form-label">VERIFICATION CODE</label><input name="code" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" placeholder="000000" required/></div><button class="btn primary" type="submit">Verify and continue →</button></form><button type="button" class="btn ghost" style="margin-top:12px" data-act="back-login">← Back to password</button>`);return;}
  authShell(`<h2>Welcome to VYRA.</h2><p>Enter your invited account credentials. All partner information stays within the assigned organization.</p><form id="login-form"><div class="form-group"><label class="form-label">WORK EMAIL</label><input type="email" name="email" required autocomplete="username" placeholder="you@company.com"/></div><div class="form-group"><label class="form-label">PASSWORD</label><input type="password" name="password" required autocomplete="current-password" placeholder="••••••••••••"/></div><button class="btn primary" type="submit">Enter risk console <span>↗</span></button></form>${state.boot?.demo_enabled?'<div class="auth-divider">EXPLICIT REVIEWER ACCESS ONLY</div><button class="btn ghost" style="width:100%" type="button" data-act="demo-login">◉ Open isolated reviewer sandbox</button><div class="outline-note">Separate reviewer workspace with synthetic data only. Enter the reviewer access code to continue.</div>':''}<div class="outline-note" style="margin-top:21px">${state.boot?.verification_mode==='EMAIL_OTP'?'Email OTP verification is enabled after your password.':'Password authentication is active. Email OTP is not configured on this server.'}${!state.boot?.owner_initialized?' Owner first-run setup is required: run setup_owner.py in the project folder.':''}</div>`);
}
const navItems=[
 ['pulse','⌁','Command overview'],['ledger','▦','Transaction ledger'],['risk','◇','Risk intelligence'],
 ['threats','◉','Threat watch'],['disputes','⚑','Dispute desk'],['model','✳','Model studio'],
 ['integrations','⇄','Integrations'],['identity','◎','Identity & About']
];
function roleLabel(role){return {owner:'PLATFORM OWNER',partner_admin:'PARTNER ADMIN',analyst:'FRAUD ANALYST',viewer:'READ ONLY',demo:'SANDBOX REVIEWER'}[role]||role;}
function appShell(){
  const me=state.me;
  const options=Object.entries(themes).map(([k,v])=>`<option value="${k}" ${document.body.dataset.theme===k?'selected':''}>${esc(v)}</option>`).join('');
  $('app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark"><span>DM</span></span><div><strong>DM – GADGET HUB</strong><small>VYRA / RISK OS</small></div></div><div class="label">OPERATIONS</div><nav id="nav-list">${navItems.concat(me.role==='owner'?[['owner','♛','Owner control']]:[]).map(([key,ic,txt])=>`<button type="button" class="nav-button ${state.tab===key?'active':''}" data-nav="${key}"><span class="nav-glyph">${ic}</span><span>${txt}</span>${key==='owner'?'<span class="nav-pill">ROOT</span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="strip" style="margin-bottom:10px;border-radius:12px;font-size:10px">${me.is_demo?'<b>ISOLATED SANDBOX</b> · Synthetic records only.':'<span class="dot" style="display:inline-block"></span> PRIVATE WORKSPACE · NO LIVE PAYMENT PROCESSING'}</div><div class="side-credit"><div class="credit-dot">${esc((me.name||'DM').split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div style="min-width:0;flex:1"><strong style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(me.name)}</strong><small>${roleLabel(me.role)}</small></div><button type="button" class="btn small icon" data-act="logout" title="Sign out" aria-label="Sign out">↗</button></div></div></aside><div class="main"><header class="topbar"><div class="breadcrumb">VYRA <span class="muted"> / </span> <b id="page-crumb">Command overview</b></div><div class="top-actions"><div class="connection"><span class="status-dot"></span> LOCAL ENGINE CONNECTED</div>${me.is_demo?'<span class="tag demo">REVIEWER SANDBOX</span>':''}<select class="theme-picker" aria-label="Color theme" id="theme-select">${options}</select><div class="user-avatar" title="${esc(me.email)}">${esc(me.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div></div></header><main class="workspace" id="work-view"></main><footer style="padding:0 36px 25px;color:var(--muted);font-size:9px;letter-spacing:1px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><span>DM – GADGET HUB · VYRA OS 2.0</span><span>ANALYST DECISIONS · NOT ISSUER AUTHORIZATIONS</span><span>© DIVY MATHUR</span></footer></div></div>`;
}
async function switchTab(key){state.tab=key;state.page=1;state.riskResult=null;
 document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===key));
 const it=navItems.concat([['owner','','Owner control']]).find(x=>x[0]===key);if($('page-crumb'))$('page-crumb').textContent=it?it[2]:key;
 const view=$('work-view');if(!view)return;view.innerHTML=`<div class="card" style="padding:50px;text-align:center;color:var(--muted)">LOADING SIGNALS ···</div>`;
 const id=++activeFetch;
 try{let html='';switch(key){
  case 'pulse':html=await pulse();break;
  case 'ledger':html=await ledger();break;
  case 'risk':html=await risk();break;
  case 'threats':html=await threats();break;
  case 'disputes':html=await disputes();break;
  case 'model':html=await model();break;
  case 'integrations':html=await integrations();break;
  case 'owner':html=await owner();break;
  case 'identity':html=await identity();break;
  default:html=empty('Unknown page','Choose an operation from the navigation.');
 }if(id===activeFetch&&$('work-view'))$('work-view').innerHTML=html;
 }catch(e){if(id===activeFetch){view.innerHTML=empty('Unable to load workspace',e.message,`<button class="btn" type="button" data-act="retry">Retry</button>`);}toast(e.message,true);}
}
function buildDailyChart(days){
 if(!days?.length)return empty('No imported transactions yet','Daily payment-risk insights appear when this workspace receives real order data.');
 const w=690,h=200,pad=16,max=Math.max(1,...days.map(x=>Number(x.count||0)));const points=days.map((d,i)=>({x:pad+i*(w-2*pad)/Math.max(1,days.length-1),y:h-pad-(Number(d.count||0)/max)*(h-2*pad)}));
 const coords=points.map(p=>`${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
 const area=`M ${points[0].x} ${h-pad} L `+points.map(p=>`${p.x} ${p.y}`).join(' L ')+` L ${points[points.length-1].x} ${h-pad} Z`;
 return `<div class="signal-canvas"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Daily transaction volume line chart"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="var(--accent)" stop-opacity=".34"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs><path d="${area}" fill="url(#area)"/><polyline points="${coords}" fill="none" stroke="var(--accent)" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3.4" fill="var(--accent)"/>`).join('')}</svg></div><div class="chart-foot"><span>${esc(days[0].day)}</span><span>MAX ${max} ORDERS / DAY</span><span>${esc(days[days.length-1].day)}</span></div>`;
}
function donut(decisions){
 const vals={APPROVE:0,CHALLENGE:0,REVIEW:0,DECLINE:0};decisions.forEach(x=>{vals[x.decision]=x.total});
 const total=Object.values(vals).reduce((a,b)=>a+b,0);
 const colors=['var(--good)','var(--blue)','var(--warn)','var(--bad)'];let offset=0;
 const segments=Object.entries(vals).map(([k,v],i)=>{const from=offset;offset+=total?100*v/total:0;return `${colors[i]} ${from}% ${offset}%`;}).join(',');
 return `<div class="donut-wrap"><div class="donut" style="background:${total?'conic-gradient('+segments+')':'var(--stroke)'}"><div class="donut-hole"><strong>${nfmt(total)}</strong><small>ANALYSED</small></div></div><div class="legend">${Object.entries(vals).map(([k,v],i)=>`<div class="legend-item"><div class="legend-left"><span class="swatch" style="background:${colors[i]}"></span>${k}</div><b>${total?Math.round(v*100/total):0}%</b></div>`).join('')}</div></div>`;
}
function orgPicker(){return state.me.role==='owner'?`<select id="org-picker" title="Select a partner workspace" style="min-width:205px"><option value="">Loading organizations</option>${state.orgs.filter(x=>x.status==='ACTIVE').map(x=>`<option value="${x.id}" ${Number(state.org)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'';}
async function pulse(){const d=await request(apiPath('/dashboard'));const m=d.metrics;
 const table=d.recent.map(x=>`<tr class="data-row" data-act="open-tx" data-id="${x.id}"><td class="mono">${esc(x.external_id)}</td><td>${esc(x.product)}</td><td>${inr(x.amount)}</td><td>${pillScore(x.risk_score)}</td><td>${tag(x.decision)}</td></tr>`).join('');
 return heading('COMMAND / 001','Know the threat. Own the response.',`Workspace: ${d.workspace_name}. Risk recommendations, merchant incidents, investigations and chargeback operations in one place.`,`${orgPicker()}<button class="btn primary" type="button" data-nav="risk">+ Analyse a transaction</button>`)+
 `${d.is_demo?'<div class="strip warn" style="margin-bottom:17px"><b>REVIEWER SANDBOX</b> · These records, events and results are synthetic. Real partners see their own data only.</div>':''}`+
 `<div class="grid-4"><div class="card metric highlight"><label>MONITORED ORDERS</label><strong>${nfmt(m.orders)}</strong><small>Records in this workspace</small><span class="glow-point">↗</span></div><div class="card metric"><label>ANALYSED VOLUME</label><strong>${inr(m.volume)}</strong><small>Uploaded transaction amounts</small><span class="glow-point">₹</span></div><div class="card metric"><label>OPEN FRAUD SIGNALS</label><strong>${nfmt(m.alerts)}</strong><small>Unresolved risk alerts</small><span class="glow-point">◉</span></div><div class="card metric"><label>OPEN DISPUTES</label><strong>${nfmt(m.open_disputes)}</strong><small>Internal case-management queue</small><span class="glow-point">⚑</span></div></div>
 <div class="hero-grid"><div class="card">${cardTitle('Transaction pulse','Daily order ingestion and operational traffic','<span class="tag">LAST 14 ACTIVE DAYS</span>')}${buildDailyChart(d.daily)}</div><div class="card">${cardTitle('Decision mix','Four transparent risk policy bands')}${donut(d.decisions)}</div></div>
 <div class="grid-2" style="margin-top:18px"><div class="card">${cardTitle('Recent intelligence','Select any order to investigate',`<button type="button" class="btn small" data-nav="ledger">Full ledger ↗</button>`)}${d.recent.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Product</th><th>Value</th><th>Risk</th><th>Decision</th></tr></thead><tbody>${table}</tbody></table></div>`:empty('Your workspace starts empty','Import a CSV or send permitted payment metadata to the API. Nothing is fabricated for a real partner.',`<button class="btn primary" data-nav="integrations" type="button">Import transactions ↗</button>`)}</div>
 <div class="card">${cardTitle('Why VYRA exists','Practical merchant decision support')}
 <div class="radar-orbit"><div class="radar-core">VY</div></div><div class="grid-2" style="margin-top:10px"><div class="strip"><strong>Before checkout</strong><br>Review device, account and velocity signals.</div><div class="strip"><strong>After checkout</strong><br>Investigate orders and collect dispute evidence.</div></div></div></div>`;
}
async function ledger(){const d=await request(apiPath(`/transactions?page=${state.page}&decision=${encodeURIComponent(state.filter)}&q=${encodeURIComponent(state.search)}`));
 return heading('DATA / 002','Transaction ledger','Search, explain and review the permitted metadata you imported. No PAN, CVV or issuer account details are stored.',`<button class="btn" type="button" data-nav="integrations">Import CSV ↗</button><button class="btn primary" type="button" data-nav="risk">New analysis</button>`)+
 `<div class="card">${cardTitle('Order intelligence',`${nfmt(d.total)} records in this workspace`)}<div class="actions" style="margin-bottom:17px"><input id="tx-search" value="${esc(state.search)}" placeholder="Order ID or product" style="flex:1;min-width:200px"/><select id="tx-filter"><option>ALL</option>${['APPROVE','CHALLENGE','REVIEW','DECLINE'].map(x=>`<option ${x===state.filter?'selected':''}>${x}</option>`).join('')}</select><button class="btn" type="button" data-act="search-transactions">Search</button></div>${d.items.length?`<div class="table-wrap"><table><thead><tr><th>Transaction ID</th><th>Time</th><th>Amount</th><th>Product</th><th>Score</th><th>Decision</th><th>Case state</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr class="data-row" data-act="open-tx" data-id="${x.id}"><td class="mono">${esc(x.external_id)}</td><td>${date(x.ts)}</td><td>${inr(x.amount)}</td><td>${esc(x.product)}</td><td>${pillScore(x.risk_score)}</td><td>${tag(x.decision)}</td><td>${tag(x.workflow)}</td><td>↗</td></tr>`).join('')}</tbody></table></div><div class="actions" style="justify-content:space-between;margin-top:19px"><span class="muted tiny">PAGE ${d.page} OF ${d.pages} · ${nfmt(d.total)} MATCHES</span><div class="actions"><button type="button" class="btn small" data-act="prev-page" ${d.page<=1?'disabled':''}>← Previous</button><button class="btn small" type="button" data-act="next-page" ${d.page>=d.pages?'disabled':''}>Next →</button></div></div>`:empty('No transactions match','Real partner workspaces never preload invented customers or orders.')}</div>`;
}
function inputText(name,label,value='',type='text',attr=''){return `<div class="form-group"><label class="form-label" for="risk-${name}">${esc(label)}</label><input id="risk-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attr}/></div>`;}
function check(name,label){return `<label class="check-item"><input type="checkbox" name="${name}"/> <span>${esc(label)}</span></label>`;}
async function risk(){return heading('INTELLIGENCE / 003','Risk decision laboratory','Evaluate real merchant-supplied payment metadata using gradient boosting plus explainable risk safeguards. Scoring never processes a payment.',`<button type="button" class="btn" data-act="preset-normal">↺ Clean order</button><button type="button" class="btn" data-act="preset-ato">ATO pattern</button><button class="btn" type="button" data-act="preset-card">Card testing</button>`)+
 `<div class="grid-2 risk-layout"><div class="card">${cardTitle('Input signals','Only low-sensitivity risk indicators; never enter card numbers or verification codes.')}
 <form id="risk-form"><div class="form-row">${inputText('transaction_id','REFERENCE ID','ORD-'+Math.random().toString(16).slice(2,9).toUpperCase())}${inputText('product','PRODUCT','Laptop')}${inputText('amount','ORDER AMOUNT (₹)',28000,'number','min="1" required')}${inputText('attempt_velocity','PAYMENT ATTEMPTS / WINDOW',1,'number','min="0"')}${inputText('failed_logins','FAILED LOGINS',0,'number','min="0"')}${inputText('declines_1h','DECLINES IN LAST HOUR',0,'number','min="0"')}${inputText('device_ref','DEVICE REFERENCE (OPAQUE)','')}${inputText('account_ref','ACCOUNT REFERENCE (OPAQUE)','')}</div><div class="form-label" style="margin:20px 0 10px">BEHAVIORAL SIGNALS</div><div class="check-grid">${check('new_address','New delivery address')}${check('new_device','Unrecognized device')}${check('recent_address_change','Recent address change')}${check('account_new','New customer account')}${check('odd_hour','Unusual transaction hour')}${check('proxy_signal','Unusual network signal')}${check('shipping_billing_mismatch','Address mismatch')}</div><div class="actions" style="margin-top:24px"><button class="btn primary" type="submit">◈ Calculate fraud risk →</button><button class="btn" type="button" data-act="save-risk" ${state.me.role==='viewer'?'disabled':''}>Save transaction</button></div></form></div><div class="stack"><div class="card" id="risk-output">${state.riskResult?riskReport(state.riskResult):`${cardTitle('Decision intelligence','Model output appears here after evaluation.')}<div class="radar-orbit"><div class="radar-core">?</div></div><div class="strip">Risk scores are recommendations for human review. Actual payment authorization remains with the issuer/gateway. Scores from the synthetic baseline require calibration before operational deployment.</div>`}</div><div class="card">${cardTitle('Four decision bands','Proposed GadgetHub policy, not Visa/Mastercard rules')}<div class="stack" style="gap:9px">${[['0–24','APPROVE','Normal authorization'],['25–49','CHALLENGE','Step-up verification'],['50–74','REVIEW','Hold fulfilment for analyst'],['75–100','DECLINE','Block the attempted order under merchant policy']].map(x=>`<div class="strip" style="display:flex;align-items:center;gap:12px"><span class="mono" style="width:55px">${x[0]}</span>${tag(x[1])}<span>${x[2]}</span></div>`).join('')}</div></div></div></div>`;}
function riskReport(r){return `${cardTitle('Risk assessment',`Model ${r.model_version} · ${r.model_source}`)}<div style="text-align:center;padding:12px 0 19px"><div class="eyebrow">EXPLAINABLE RISK SCORE</div><div style="font-weight:900;letter-spacing:-4px;font-size:73px;line-height:1.05;color:${r.risk_score>=75?'var(--bad)':r.risk_score>=50?'var(--warn)':'var(--accent)'}">${r.risk_score}<span style="font-size:21px;letter-spacing:0;color:var(--muted)">/100</span></div>${tag(r.decision)}<div class="helper" style="margin-top:15px">ML fraud probability (uncalibrated): ${(r.risk_probability*100).toFixed(1)}% · Policy rule points: ${r.rule_points}</div></div><div class="progress"><span style="width:${r.risk_score}%;background:${r.risk_score>=75?'var(--bad)':r.risk_score>=50?'var(--warn)':'var(--accent)'}"></span></div><div class="divider"></div><div class="card-title">Risk drivers & guardrails</div>${r.guardrails?.map(x=>`<div class="strip warn" style="margin-top:12px">⚠ ${esc(x)}</div>`).join('')||''}${r.reasons?.map(x=>`<div class="factor"><span>${esc(x.factor)}</span><b>${x.weight}</b></div>`).join('')||''}<div class="strip" style="margin-top:16px">${esc(r.disclaimer)}</div>`;}
async function threats(){const [data,alerts]=await Promise.all([request(apiPath('/attack')),request(apiPath('/alerts'))]);
 return heading('MONITOR / 004','Threat watch','Investigate suspicious transaction patterns and acknowledge high-priority events. New alerts are generated from imported or ingested transactions.',`<button class="btn" type="button" data-act="refresh">↻ Refresh intelligence</button>`)+
 `<div class="grid-3"><div class="card metric"><label>LOW-VALUE EVENTS</label><strong>${nfmt(data.synthetic_attempts+data.uploaded_micro_transactions)}</strong><small>${data.is_synthetic?'Synthetic + imported events':'Imported orders ≤ ₹5'}</small></div><div class="card metric"><label>HIGH-RISK MICRO TRANSACTIONS</label><strong>${nfmt(data.uploaded_high_risk_micro_transactions)}</strong><small>Scored transactions needing attention</small></div><div class="card metric"><label>ACTIVE ALERTS</label><strong>${nfmt(alerts.items.filter(a=>a.status!=='RESOLVED').length)}</strong><small>Across this organization only</small></div></div>
 ${data.is_synthetic?`<div class="strip warn" style="margin:17px 0">This sandbox includes the <b>3,000 × ₹1</b> card-testing scenario as fictional attack events. No card network requests are executed.</div>`:''}
 <div class="grid-2" style="margin-top:18px"><div class="card">${cardTitle('Suspicious activity feed','Event detections from this workspace')}${alerts.items.length?alerts.items.map(a=>`<div class="strip" style="margin-bottom:10px;display:flex;justify-content:space-between;gap:13px"><div><div style="margin-bottom:7px">${tag(a.severity)} ${tag(a.status)}</div><strong>${esc(a.title)}</strong><div class="muted tiny" style="margin-top:6px">${esc(a.detail)}</div><div class="muted tiny" style="margin-top:4px">${date(a.created_at)}</div></div><div class="actions" style="align-self:center">${state.me.role==='viewer'?'':`<button type="button" class="btn small" data-act="ack-alert" data-id="${a.id}">Acknowledge</button><button type="button" class="btn small" data-act="resolve-alert" data-id="${a.id}">Resolve</button>`}</div></div>`).join(''):empty('Quiet workspace','Alerts appear when a high-risk transaction is ingested or saved.')}</div><div class="stack"><div class="card">${cardTitle('Attack detection logic','What actually triggers a response')}
 <div class="strip accent"><strong>01 · Payment velocity</strong><br>Repeated attempts from the same tokenized device/reference or high velocity reported by the gateway.</div><div class="strip" style="margin-top:9px"><strong>02 · Low-value enumeration</strong><br>Very small amounts combined with high attempts are escalated to DECLINE.</div><div class="strip" style="margin-top:9px"><strong>03 · Account takeover</strong><br>New device + recent shipping change + failed logins triggers a risk safeguard.</div><div class="strip" style="margin-top:9px"><strong>04 · Investigator action</strong><br>Analysts acknowledge, research and close alerts; VYRA does not directly block an issuer.</div></div><div class="card">${cardTitle('Operating controls','Defensive steps on the actual gateway')}<div class="stack" style="gap:8px">${['Use gateway-side velocity caps and bot challenges','Apply step-up authentication through supported payment providers','Review orders before dispatching high-value electronics','Verify customer reports and provide a safe appeal route'].map(x=>`<div class="inline-state"><span class="dot"></span>${x}</div>`).join('')}</div></div></div></div>`;}
async function disputes(){const d=await request(apiPath('/disputes'));const editable=state.me.role!=='viewer';
 return heading('CASEWORK / 005','Dispute resolution desk','Organize customer complaints, evidence references and response deadlines. Internal status changes do not submit anything to a card network.',editable?`<button type="button" class="btn primary" data-act="new-dispute">+ New case</button>`:'')+
 `<div class="card">${cardTitle('Open & historical cases',`${d.items.length} dispute cases · Each stays inside its own organization`)}${d.items.length?`<div class="table-wrap"><table><thead><tr><th>Case</th><th>Order</th><th>Reason</th><th>Disputed value</th><th>Due date</th><th>Status</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr class="data-row" data-act="open-dispute" data-id="${x.id}"><td class="mono">${esc(x.case_ref)}</td><td>${esc(x.order_id)}</td><td>${esc(x.reason)}</td><td>${inr(x.amount)}</td><td>${date(x.due_date)}</td><td>${tag(x.status)}</td><td>↗</td></tr>`).join('')}</tbody></table></div>`:empty('No disputes recorded','Create an internal dispute case when a cardholder disputes an electronics purchase. Add the correct response deadline from your acquirer.',editable?'<button type="button" class="btn primary" data-act="new-dispute">Start a case ↗</button>':'') }</div>
 <div class="grid-3" style="margin-top:17px"><div class="strip"><strong>Collect evidence</strong><br>Order receipt, delivery details, communications and refund history.</div><div class="strip"><strong>Respect deadlines</strong><br>Use the issuer/acquirer deadline for the individual dispute reason code.</div><div class="strip"><strong>Record the outcome</strong><br>Won, lost, accepted or closed. Keep a documented audit trail.</div></div>`;
}
async function model(){const d=await request(apiPath('/model'));const m=d.model,labels=d.labels,trainable=['owner','partner_admin'].includes(state.me.role);
 return heading('RESEARCH / 006','Model studio','A real executable machine-learning pipeline for tabular risk features, with clear boundaries between synthetic experiments and operational claims.',trainable?'<button type="button" class="btn primary" data-act="train-model">↻ Train on reviewed labels</button>':'')+
 `<div class="grid-3"><div class="card metric highlight"><label>MODEL SOURCE</label><strong style="font-size:20px;line-height:1.2">${m.source==='synthetic'?'SYNTHETIC':'PARTNER LABELS'}</strong><small>${esc(m.version)}</small></div><div class="card metric"><label>REVIEWED LABELS</label><strong>${nfmt(labels.n)}</strong><small>${labels.fraud} fraud / ${labels.legit} legitimate</small></div><div class="card metric"><label>VALIDATION AUC</label><strong>${m.metrics.auc===null?'—':m.metrics.auc}</strong><small>${m.source==='synthetic'?'Synthetic holdout · not live accuracy':'Held-out labelled partner records'}</small></div></div>
 <div class="grid-2" style="margin-top:18px"><div class="card">${cardTitle('Prediction engine','Histogram Gradient Boosting + deterministic policy guardrails')}
 <div class="stack" style="gap:12px">${[['Precision',m.metrics.precision],['Recall',m.metrics.recall],['False positive rate',m.metrics.false_positive_rate]].map(([k,v])=>`<div><div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:7px"><span>${esc(k)}</span><b>${v===undefined?'—':(Number(v)*100).toFixed(1)+'%'}</b></div><div class="progress"><span style="width:${Number(v||0)*100}%"></span></div></div>`).join('')}</div><div class="strip warn" style="margin-top:20px"><b>Meaning of these numbers:</b> ${m.source==='synthetic'?'The model was trained/tested on generated labels. These metrics DO NOT demonstrate real fraud detection performance.':'These metrics come from a chronological labelled test split. Dataset shift, label quality and calibration must still be validated before payment decisions.'}</div></div>
 <div class="card">${cardTitle('Feature space','Signals accepted from merchant systems')}
 <div class="grid-2" style="gap:9px">${d.features.map((x,i)=>`<div class="strip mono"><span style="color:var(--blue)">${String(i+1).padStart(2,'0')}</span> ${esc(x)}</div>`).join('')}</div><div class="divider"></div><div class="card-title">Retraining requirements</div><p class="muted" style="font-size:11px;line-height:1.9">Upload transaction metadata, review the outcomes, then label confirmed cases as 1 (fraud) or 0 (legitimate). A new model requires ≥100 labelled transactions, at least 15 fraud and 35 legitimate. An 80/20 chronological split is used.</p></div></div>
 <div class="card" style="margin-top:17px">${cardTitle('Human-in-the-loop policy','ML informs decisions; transparent rules enforce critical guardrails')}<div class="grid-4">${Object.entries(d.bands).map(([decision,range])=>`<div class="strip"><div class="eyebrow">${range}</div>${tag(decision)}</div>`).join('')}</div></div>`;
}
async function integrations(){const canKey=['owner','partner_admin'].includes(state.me.role);const editable=state.me.role!=='viewer';let keys=[];if(canKey){const k=await request(apiPath('/integrations/keys'));keys=k.items;}
 return heading('CONNECT / 007','Data & integrations','Move from a static prototype to a practical risk service: upload permitted transaction metadata or post it from a merchant backend.',`<button type="button" class="btn" data-act="download-template">↓ CSV schema</button>`)+
 `<div class="grid-2"><div class="card">${cardTitle('Import transactions','CSV ingestion immediately persists and scores each row')}
 ${editable?`<form id="import-form"><div class="strip" style="margin-bottom:18px">Required columns: <code>transaction_id</code>, <code>amount</code>. Optional fields include product, device_ref, payment_status, timestamp, risk flags and confirmed fraud labels. Maximum 5 MB / 5,000 rows.</div><div class="form-group"><label class="form-label">SELECT YOUR MERCHANT CSV</label><input type="file" id="csv-file" accept=".csv,text/csv" required/></div><div class="actions" style="margin-top:20px"><button type="submit" class="btn primary">Import & score transactions →</button><button type="button" class="btn" data-act="download-template">Get template</button></div></form>`:empty('Viewer account','Your role can inspect permitted records but cannot import or change data.')}
 <div class="strip warn" style="margin-top:20px">Never upload raw card numbers, CVV/CVC, passwords, bank account credentials or other forbidden payment credentials.</div></div>
 <div class="card">${cardTitle('Developer integration','Send one order from a backend service using a workspace API key')}<div class="code">POST /api/ingest\nX-API-Key: vyra_********\nContent-Type: application/json\n\n{\n  "transaction_id": "SHOP-105",\n  "amount": 48000,\n  "product": "Laptop",\n  "device_ref": "browser-device-8",\n  "payment_status": "DECLINED",\n  "new_device": true,\n  "recent_address_change": true,\n  "failed_logins": 4,\n  "attempt_velocity": 2\n}</div><div class="helper" style="margin-top:14px">Create an API key below. Use HTTPS in hosted environments. Never send payment credentials or expose an API key in browser JavaScript.</div></div></div>
 <div class="card" style="margin-top:17px">${cardTitle('Workspace API keys','Scoped to the active organization; secret displayed once',canKey?'<button type="button" class="btn primary small" data-act="create-api-key">+ Issue API key</button>':'')}
 ${!canKey?empty('Restricted feature','Only a partner admin or platform owner can issue integration keys.'):keys.length?`<div class="table-wrap"><table><thead><tr><th>Connector</th><th>Created</th><th>State</th><th></th></tr></thead><tbody>${keys.map(k=>`<tr><td>${esc(k.name)}</td><td>${date(k.created_at)}</td><td>${tag(k.revoked?'REVOKED':'ACTIVE')}</td><td>${k.revoked?'':`<button type="button" class="btn small danger" data-act="revoke-key" data-id="${k.id}">Revoke</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('No API keys issued','Your partner backend can securely send transaction events when you create a scoped key.')}</div>`;
}
async function owner(){if(state.me.role!=='owner')return empty('Restricted','Owner account is required.');
 const [orgs,users]=await Promise.all([request('/admin/orgs'),request('/admin/users')]);state.orgs=orgs.items;
 return heading('GOVERNANCE / ROOT','Owner control room','You control which organizations exist, who can sign in, and which workspaces are suspended. Sensitive server settings are never shown to partners.',`<button type="button" class="btn" data-act="invite-user">+ Invite partner</button><button class="btn primary" type="button" data-act="new-org">+ New workspace</button>`)+
 `<div class="grid-3"><div class="card metric highlight"><label>PARTNER WORKSPACES</label><strong>${nfmt(orgs.items.length-1)}</strong><small>Excluding headquarters / sandbox</small></div><div class="card metric"><label>REGISTERED PEOPLE</label><strong>${nfmt(users.items.length)}</strong><small>Invited users, including owner</small></div><div class="card metric"><label>ACTIVE ACCOUNTS</label><strong>${nfmt(users.items.filter(x=>x.active).length)}</strong><small>Access can be revoked instantly</small></div></div>
 <div class="card" style="margin-top:18px">${cardTitle('Partner organizations','Suspension revokes active sessions and blocks access')}
 <div class="table-wrap"><table><thead><tr><th>Workspace</th><th>People</th><th>Transactions</th><th>Status</th><th>Actions</th></tr></thead><tbody>${orgs.items.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.user_count}</td><td>${x.transaction_count}</td><td>${tag(x.status)}</td><td><div class="actions"><button class="btn small" data-act="select-org" data-id="${x.id}" type="button">Inspect</button>${x.id===state.me.org_id?'':`<button type="button" class="btn small ${x.status==='ACTIVE'?'danger':''}" data-act="toggle-org" data-id="${x.id}" data-next="${x.status==='ACTIVE'?'SUSPENDED':'ACTIVE'}">${x.status==='ACTIVE'?'Suspend':'Reactivate'}</button>`}</div></td></tr>`).join('')}</tbody></table></div></div>
 <div class="card" style="margin-top:18px">${cardTitle('Authorized people','An owner can suspend partner accounts but cannot read their passwords')}
 <div class="table-wrap"><table><thead><tr><th>Account</th><th>Email</th><th>Workspace</th><th>Role</th><th>Access</th><th>Last sign-in</th><th>Sessions</th><th></th></tr></thead><tbody>${users.items.map(x=>`<tr><td>${esc(x.display_name)}</td><td>${esc(x.email)}</td><td>${esc(x.org_name)}</td><td>${tag(x.role)}</td><td>${tag(x.active?'ACTIVE':'SUSPENDED')}</td><td>${x.last_login?date(x.last_login):'Never'}</td><td>${x.active_sessions||0}</td><td>${x.role==='owner'?'OWNER':`<button type="button" data-act="revoke-session" data-id="${x.id}" class="btn small">End sessions</button> <button type="button" data-act="toggle-user" data-id="${x.id}" data-next="${x.active?'false':'true'}" class="btn small ${x.active?'danger':''}">${x.active?'Suspend':'Restore'}</button>`}</td></tr>`).join('')}</tbody></table></div></div><div class="strip accent" style="margin-top:17px">Only <strong>Divy Mathur’s owner account</strong> can use this screen. Partner sessions are scoped to their own workspace, and the reviewer sandbox is completely separate.</div>`;
}
async function identity(){return heading('PROFILE / 008','Identity, trust & ownership','Your account, creator credits and the security boundary of this platform.')+
 `<div class="grid-2"><div class="card">${cardTitle('Current account','This profile is private to your signed-in account')}
 ${[['Display name',state.me.name],['Email address',state.me.email],['Access level',roleLabel(state.me.role)],['Workspace',state.me.org_name],['Email code verification',state.me.otp_enabled?'Enabled after password':'Not configured on server'],['Operational mode',state.me.is_demo?'Reviewer sandbox':'Private merchant workspace']].map(([k,v])=>`<div class="factor"><span class="muted">${esc(k)}</span><b style="text-align:right;word-break:break-word;max-width:55%">${esc(v)}</b></div>`).join('')}
 ${state.me.role!=='demo'?`<div class="actions" style="margin-top:20px"><button type="button" class="btn" data-act="change-password">Change password ↗</button></div>`:''}</div>
 <div class="card">${cardTitle('Built by Divy Mathur','Creator identity is public to all users; technical configuration is not.')}
 <div class="radar-orbit"><div class="radar-core">DM</div></div><div style="text-align:center"><div class="eyebrow">OWNER & CREATOR</div><h2 style="margin:8px 0;letter-spacing:-1px">Divy Mathur</h2><a class="muted" href="mailto:divymathur12345678901@gmail.com">divymathur12345678901@gmail.com</a></div><div class="divider"></div><p class="muted" style="font-size:11px;line-height:1.9">VYRA is an educational fraud-analysis and dispute-operations application for GadgetHub’s fintech capstone. Merchant records are isolated by organization. Scores are advisory only; no issuer/gateway funds are moved.</p></div></div>
 <div class="card" style="margin-top:17px">${cardTitle('Security boundary','Operational transparency without leaking private server settings')}
 <div class="grid-3"><div class="strip"><strong>Partner separation</strong><br>Accounts cannot query another tenant's transactions, alerts, labels or disputes.</div><div class="strip"><strong>Owner authority</strong><br>Only the owner may create/suspend organizations and invite or suspend partner accounts.</div><div class="strip"><strong>Honest model status</strong><br>Simulation-only metrics are labelled; no real payment approvals or card-network actions.</div></div></div>`;
}
function openModal(title,body){const root=$('modal');root.hidden=false;root.innerHTML=`<section class="modal-panel" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h3>${esc(title)}</h3><button type="button" class="close-btn" data-close aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div></section>`;const btn=root.querySelector('[data-close]');if(btn)btn.focus();}
function closeModal(){const root=$('modal');root.hidden=true;root.innerHTML='';}
function formObject(f){const d={};new FormData(f).forEach((v,k)=>{d[k]=v});return d;}
function riskPayload(){const form=$('risk-form');if(!form)throw new Error('Open the Risk Intelligence page first');let d=formObject(form);for(const field of ['new_address','new_device','recent_address_change','account_new','odd_hour','proxy_signal','shipping_billing_mismatch'])d[field]=Boolean(form.elements[field]?.checked);for(const f of ['amount','attempt_velocity','failed_logins','declines_1h'])d[f]=Number(d[f]||0);return d;}
function setPreset(p){const f=$('risk-form');if(!f)return;f.reset();const settings={normal:{amount:28000,attempt_velocity:1,failed_logins:0,declines_1h:0},ato:{amount:65000,attempt_velocity:4,failed_logins:6,declines_1h:4,new_address:true,new_device:true,recent_address_change:true,shipping_billing_mismatch:true},card:{amount:1,attempt_velocity:30,failed_logins:0,declines_1h:20,new_device:true,proxy_signal:true}}[p];
 for(const [k,v] of Object.entries(settings)){const el=f.elements[k];if(!el)continue;if(el.type==='checkbox')el.checked=!!v;else el.value=v;}
 toast(p==='normal'?'Clean order loaded':'Investigation preset loaded. These are illustrative signals.');}
async function openTransaction(id){const record=await request(apiPath('/transactions/'+Number(id)));
 const disabled=state.me.role==='viewer'?'disabled':'';
 openModal('Order '+record.external_id,`<div class="grid-3"><div class="strip"><div class="eyebrow">AMOUNT</div><strong>${inr(record.amount)}</strong></div><div class="strip"><div class="eyebrow">RISK</div>${pillScore(record.risk_score)}</div><div class="strip"><div class="eyebrow">DECISION</div>${tag(record.decision)}</div></div><div class="divider"></div>${cardTitle('Risk signals','Features and reasons captured at the time of analysis')}${record.reasons?.map(x=>`<div class="factor"><span>${esc(x.factor)}</span><b>${esc(x.weight)}</b></div>`).join('')||''}<div class="strip" style="margin-top:15px">Source: ${esc(record.source)} · Model: ${esc(record.model)}. Payment approval remains with the real gateway/issuer.</div><div class="divider"></div><form id="review-form" data-id="${record.id}"><div class="form-row"><div class="form-group"><label class="form-label">INVESTIGATION STATE</label><select name="workflow" ${disabled}>${['NEW','IN_REVIEW','CLEARED','ESCALATED','CLOSED'].map(s=>`<option ${s===record.workflow?'selected':''}>${s}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">REVIEWED FRAUD LABEL</label><select name="fraud_label" ${disabled}><option value="">Unconfirmed</option><option value="0" ${record.fraud_label===0?'selected':''}>0 · Legitimate</option><option value="1" ${record.fraud_label===1?'selected':''}>1 · Confirmed fraud</option></select></div></div><div class="form-group" style="margin-top:14px"><label class="form-label">ANALYST NOTES</label><textarea name="notes" ${disabled}>${esc(record.notes)}</textarea></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button>${disabled?'':`<button type="submit" class="btn primary">Save review ↗</button>`}</div></form>`);
}
async function loadDispute(id){const d=await request(apiPath('/disputes'));const item=d.items.find(x=>x.id===Number(id));if(!item)throw new Error('Case not found');
 const editable=state.me.role!=='viewer';const disabled=editable?'':'disabled';
 openModal('Dispute / '+item.case_ref,`<div class="strip"><b>Order:</b> ${esc(item.order_id)} · <b>Amount:</b> ${inr(item.amount)}<br><b>Reason:</b> ${esc(item.reason)}<br><b>Deadline:</b> ${date(item.due_date)}</div><form id="dispute-update-form" data-id="${item.id}"><div class="form-group" style="margin-top:18px"><label class="form-label">INTERNAL CASE STATUS</label><select name="status" ${disabled}>${['OPEN','GATHERING','READY','SUBMITTED','WON','LOST','ACCEPTED','CLOSED'].map(s=>`<option ${s===item.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="form-label" style="margin:19px 0 10px">EVIDENCE REFERENCES · DO NOT ENTER CARD CREDENTIALS</div><div class="form-row">${[['receipt','Receipt reference'],['authentication','Issuer authentication reference'],['shipping','Delivery tracking'],['communication','Customer correspondence'],['refund','Refund trail'],['device','Permitted device signals']].map(([k,l])=>`<div class="form-group"><label class="form-label">${l.toUpperCase()}</label><input name="${k}" ${disabled} value="${esc(item.evidence?.[k]||'')}" placeholder="Case ID / available"/></div>`).join('')}</div><div class="form-group" style="margin-top:15px"><label class="form-label">CASE NOTES</label><textarea name="notes" ${disabled}>${esc(item.notes)}</textarea></div><div class="strip warn" style="margin-top:14px">An internal status of SUBMITTED does not send evidence to a bank. The analyst must submit through the correct acquirer channel.</div><div class="modal-actions"><button type="button" class="btn" data-act="export-evidence" data-id="${item.id}">↓ Evidence JSON</button>${editable?'<button type="submit" class="btn primary">Save case status ↗</button>':''}</div></form>`);
}
function modalNewDispute(){openModal('New chargeback case',`<form id="new-dispute-form"><div class="form-row"><div class="form-group"><label class="form-label">ORDER REFERENCE</label><input required name="order_id" placeholder="ORDER-1045"/></div><div class="form-group"><label class="form-label">DISPUTED AMOUNT (₹)</label><input name="amount" type="number" required min="1" placeholder="28000"/></div></div><div class="form-group" style="margin-top:15px"><label class="form-label">DISPUTE REASON</label><select name="reason"><option>Unauthorized transaction</option><option>Item not received</option><option>Product not as described</option><option>Credit not processed</option><option>Duplicate processing</option></select></div><div class="form-group" style="margin-top:15px"><label class="form-label">RESPONSE DEADLINE (UTC / ISO)</label><input name="due_date" required value="${new Date(Date.now()+3*86400000).toISOString()}"/></div><div class="strip" style="margin-top:18px">Read the actual dispute deadline and reason-code requirements from your acquirer; 72 hours here is an editable starting placeholder, not a network rule.</div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">Create case ↗</button></div></form>`);}
function modalNewOrg(){openModal('Create partner workspace',`<form id="new-org-form"><div class="form-group"><label class="form-label">PARTNER ORGANIZATION NAME</label><input required minlength="3" maxlength="100" name="name" placeholder="Retail partner · South"/></div><div class="strip" style="margin-top:16px">Each organization starts empty. Its users and transaction data are isolated from other partners.</div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Create organization ↗</button></div></form>`);}
function modalInvite(){openModal('Invite a partner account',`<form id="invite-form"><div class="form-group"><label class="form-label">PARTNER EMAIL</label><input type="email" required name="email" placeholder="analyst@partner.com"/></div><div class="form-row" style="margin-top:15px"><div class="form-group"><label class="form-label">WORKSPACE</label><select name="org_id" required>${state.orgs.filter(o=>o.status==='ACTIVE').map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">ROLE</label><select name="role"><option value="analyst">Analyst · investigate & review</option><option value="partner_admin">Partner admin · integrations & model</option><option value="viewer">Viewer · read only</option></select></div></div><div class="strip" style="margin-top:17px">A single-use activation link is generated for 48 hours. Send it privately to your partner. This prototype does not automatically email invitations.</div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">Generate secure invite ↗</button></div></form>`);}
function modalChangePassword(){openModal('Change my password',`<form id="password-form"><div class="form-group"><label class="form-label">CURRENT PASSWORD</label><input name="old" type="password" required autocomplete="current-password"/></div><div class="form-group" style="margin-top:15px"><label class="form-label">NEW PASSWORD · 12+ CHARACTERS</label><input name="new" type="password" minlength="12" required autocomplete="new-password"/></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Change password</button></div></form>`);}
function saveDownload(name,content,type='application/json'){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},250);}
function detailsHtml(k,v){return `<div class="factor"><span class="muted">${esc(k)}</span><strong>${esc(v)}</strong></div>`;}
// Global delegated event handling. Explicit button types prevent accidental form submits.
document.addEventListener('click',ev=>{
 const close=ev.target.closest('[data-close]');if(close){ev.preventDefault();ev.stopPropagation();closeModal();return;}
 if(ev.target===$('modal')){closeModal();return;}
 const nav=ev.target.closest('[data-nav]');if(nav){ev.preventDefault();safeRun(switchTab(nav.dataset.nav));return;}
 const el=ev.target.closest('[data-act]');if(!el)return;ev.preventDefault();const act=el.dataset.act;
 if(act.startsWith('theme-')){setTheme(act.slice(6));authView();return;}
 if(act==='back-login'){state.pendingChallenge=null;authView();return;}
 if(act==='retry'||act==='refresh'){safeRun(switchTab(state.tab));return;}
 if(act==='logout'){safeRun(request('/auth/logout',{method:'POST'}).then(()=>{state.me=null;state.pendingChallenge=null;authView();toast('Signed out');}));return;}
 if(act==='demo-login'){
   const code=window.prompt('Reviewer access code (provided by the project owner):');
   if(code===null)return;
   safeRun(request('/auth/demo',{method:'POST',body:{code}}).then(()=>loadUser()));
   return;
 }
 if(act.startsWith('preset-')){setPreset(act.slice(7));return;}
 if(act==='save-risk'){safeRun((async()=>{const d=await request(apiPath('/transactions'),{method:'POST',body:riskPayload()});state.riskResult=d;toast('Saved: '+d.transaction_id+' · '+d.decision);switchTab('ledger');})());return;}
 if(act==='search-transactions'){state.search=$('tx-search')?.value.trim()||'';state.filter=$('tx-filter')?.value||'ALL';state.page=1;safeRun(switchTab('ledger'));return;}
 if(act==='prev-page'||act==='next-page'){state.page=Math.max(1,state.page+(act==='next-page'?1:-1));safeRun(switchTab('ledger'));return;}
 if(act==='open-tx'){safeRun(openTransaction(el.dataset.id));return;}
 if(act==='open-dispute'){safeRun(loadDispute(el.dataset.id));return;}
 if(act==='new-dispute'){modalNewDispute();return;}
 if(act==='new-org'){modalNewOrg();return;}
 if(act==='invite-user'){modalInvite();return;}
 if(act==='change-password'){modalChangePassword();return;}
 if(act==='download-template'){safeRun((async()=>{const r=await fetch('/api/template',{credentials:'same-origin'});if(!r.ok)throw new Error('Unable to download template');saveDownload('vyra_import_template.csv',await r.text(),'text/csv');})());return;}
 if(act==='export-evidence'){safeRun(request(apiPath('/disputes/'+el.dataset.id+'/evidence')).then(p=>{saveDownload('VYRA_evidence_'+el.dataset.id+'.json',JSON.stringify(p,null,2));toast('Evidence packet exported');}));return;}
 if(act==='ack-alert'||act==='resolve-alert'){safeRun(request(apiPath('/alerts/'+el.dataset.id),{method:'PATCH',body:{status:act==='ack-alert'?'ACKNOWLEDGED':'RESOLVED'}}).then(()=>{toast('Alert updated');switchTab('threats');}));return;}
 if(act==='train-model'){if(!confirm('Train an organization-specific model from reviewed, labelled orders? This replaces the previous organization model.'))return;safeRun(request(apiPath('/model/train'),{method:'POST',body:{}}).then(()=>{toast('New model trained from partner labels');switchTab('model');}));return;}
 if(act==='create-api-key'){openModal('Create merchant API key',`<form id="key-form"><div class="form-group"><label class="form-label">CONNECTOR NAME</label><input name="name" required placeholder="Checkout gateway integration"/></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Issue key ↗</button></div></form>`);return;}
 if(act==='revoke-key'){if(!confirm('Revoke this connector key now? The partner integration will stop accepting it.'))return;safeRun(request(apiPath('/integrations/keys/'+el.dataset.id),{method:'PATCH',body:{}}).then(()=>{toast('Key revoked');switchTab('integrations');}));return;}
 if(act==='select-org'){state.org=Number(el.dataset.id);toast('Inspecting selected workspace');safeRun(switchTab('pulse'));return;}
 if(act==='toggle-org'){if(!confirm('Change organization status to '+el.dataset.next+'? Suspension revokes partner sessions.'))return;safeRun(request('/admin/orgs/'+el.dataset.id,{method:'PATCH',body:{status:el.dataset.next}}).then(()=>{toast('Organization updated');switchTab('owner');}));return;}
 if(act==='revoke-session'){if(!confirm('End all current sessions for this partner?'))return;safeRun(request('/admin/users/'+el.dataset.id+'/revoke-sessions',{method:'POST',body:{}}).then(()=>{toast('Partner sessions revoked');switchTab('owner');}));return;}
 if(act==='toggle-user'){if(!confirm('Change partner access?'))return;safeRun(request('/admin/users/'+el.dataset.id,{method:'PATCH',body:{active:el.dataset.next==='true'}}).then(()=>{toast('Partner account updated');switchTab('owner');}));return;}
});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!$('modal').hidden)closeModal();if(ev.key==='Enter'&&ev.target.id==='tx-search'){ev.preventDefault();state.search=ev.target.value.trim();state.page=1;safeRun(switchTab('ledger'));}});
document.addEventListener('change',ev=>{if(ev.target.id==='theme-select')setTheme(ev.target.value);if(ev.target.id==='org-picker'){state.org=Number(ev.target.value);safeRun(switchTab(state.tab));}});
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.id)return;ev.preventDefault();safeRun(handleForm(f));});
async function handleForm(f){const d=formObject(f);
 switch(f.id){
  case 'login-form':{
    const r=await request('/auth/login',{method:'POST',body:d});
    if(r.otp_required){state.pendingChallenge=r;authView();toast('Verification code sent');}else await loadUser();break;}
  case 'otp-form':{
    await request('/auth/verify',{method:'POST',body:{challenge:state.pendingChallenge?.challenge,code:d.code}});
    state.pendingChallenge=null;await loadUser();break;}
  case 'activation-form':{
    const token=new URLSearchParams(location.search).get('invite');await request('/auth/activate',{method:'POST',body:{...d,token}});history.replaceState({},'',location.pathname);toast('Partner account activated. You can sign in.');authView();break;}
  case 'risk-form':{
    const r=await request(apiPath('/risk/evaluate'),{method:'POST',body:riskPayload()});state.riskResult=r;
    const out=$('risk-output');if(out)out.innerHTML=riskReport(r);toast('Analysis completed · '+r.decision);break;}
  case 'import-form':{
    const file=$('csv-file')?.files?.[0];if(!file)throw new Error('Please select a CSV first');if(file.size>5*1024*1024)throw new Error('Maximum file size is 5 MB');
    const res=await request(apiPath('/transactions/import'),{method:'POST',body:await file.text(),raw:true});
    openModal('CSV ingestion complete',`<div class="grid-2"><div class="strip">Imported <h2>${res.inserted}</h2> transactions</div><div class="strip">Skipped <h2>${res.skipped}</h2> transactions</div></div>${res.errors?.length?`<div class="card-title" style="margin-top:18px">First validation issues</div><div class="code">${esc(JSON.stringify(res.errors,null,2))}</div>`:''}<div class="strip" style="margin-top:15px">${esc(res.note)}</div><div class="modal-actions"><button type="button" class="btn primary" data-close>Done</button></div>`);
    toast('Imported '+res.inserted+' records');break;}
  case 'review-form':{
    const label=d.fraud_label===''?null:Number(d.fraud_label);
    await request(apiPath('/transactions/'+f.dataset.id+'/review'),{method:'PATCH',body:{workflow:d.workflow,notes:d.notes,fraud_label:label}});
    closeModal();toast('Investigation saved');await switchTab('ledger');break;}
  case 'new-dispute-form':{
    await request(apiPath('/disputes'),{method:'POST',body:d});closeModal();toast('Internal case created');await switchTab('disputes');break;}
  case 'dispute-update-form':{
    const evidence={receipt:d.receipt,authentication:d.authentication,shipping:d.shipping,communication:d.communication,refund:d.refund,device:d.device};
    await request(apiPath('/disputes/'+f.dataset.id),{method:'PATCH',body:{status:d.status,notes:d.notes,evidence}});
    closeModal();toast('Case updated');await switchTab('disputes');break;}
  case 'new-org-form':{
    await request('/admin/orgs',{method:'POST',body:d});closeModal();toast('Private partner organization created');await switchTab('owner');break;}
  case 'invite-form':{
    const r=await request('/admin/invite',{method:'POST',body:{...d,org_id:Number(d.org_id)}});
    const inviteUrl=location.origin+r.invite_path;
    openModal('Secure invite link',`<div class="strip accent"><strong>${esc(r.recipient)}</strong><br>Single-use activation link · expires after 48 hours.</div><div class="form-group" style="margin-top:18px"><label class="form-label">PRIVATE INVITATION LINK</label><input id="invite-link" readonly value="${esc(inviteUrl)}" style="width:100%"/></div><div class="modal-actions"><button type="button" class="btn" data-act="copy-invite">Copy link</button><button type="button" class="btn primary" data-close>Done</button></div><div class="helper" style="margin-top:12px">Send privately to the correct partner. Localhost links work only on your own computer; publish behind HTTPS for remote partners.</div>`);break;}
  case 'password-form':{
    await request('/auth/password',{method:'POST',body:d});closeModal();toast('Password changed and other sessions revoked');break;}
  case 'key-form':{
    const r=await request(apiPath('/integrations/keys'),{method:'POST',body:d});
    openModal('Save your API key now',`<div class="strip warn">This key is displayed only once. Anyone holding it can submit allowed transaction metadata to this workspace.</div><div class="form-group" style="margin-top:18px"><label class="form-label">SCOPED SECRET</label><textarea id="new-api-key" readonly style="width:100%;height:86px">${esc(r.key)}</textarea></div><div class="modal-actions"><button type="button" class="btn" data-act="copy-key">Copy secret</button><button type="button" class="btn primary" data-close>I saved the key</button></div>`);break;}
 }
}
document.addEventListener('click',ev=>{
 const a=ev.target.closest('[data-act="copy-invite"], [data-act="copy-key"]');if(!a)return;ev.preventDefault();
 const field=$(a.dataset.act==='copy-invite'?'invite-link':'new-api-key');if(!field)return;
 const txt=field.value;
 if(navigator.clipboard?.writeText){navigator.clipboard.writeText(txt).then(()=>toast('Copied securely')).catch(()=>{field.select();toast('Select and copy the highlighted text');});}
 else{field.select();toast('Select and copy the highlighted text');}
});
async function loadUser(){state.me=await request('/me');
 if(state.me.role==='owner'){
  try{state.orgs=(await request('/admin/orgs')).items;}catch{state.orgs=[];}
  if(!state.org)state.org=state.me.org_id;
 }else{state.org=state.me.org_id;state.orgs=[];}
 state.tab='pulse';appShell();await switchTab('pulse');}
async function boot(){try{state.boot=await request('/bootstrap');try{state.me=await request('/me');}catch{state.me=null;}if(state.me)await loadUser();else authView();}
 catch(e){$('app').innerHTML=`<div style="max-width:540px;margin:14vh auto;padding:30px" class="card"><h1>VYRA server unavailable</h1><p class="muted">${esc(e.message)}</p><p class="muted">Start <b>run.bat</b> to run the backend. Opening static/index.html directly cannot power authentication, partner accounts, ML inference or case management.</p><button class="btn primary" onclick="location.reload()">Retry connection</button></div>`;}}
boot();
